-- DuckPlan initial D1 (SQLite) schema: accounts, sessions, classes, items, Axis connections,
-- sync runs, reminders. Ported from the earlier Supabase/Postgres schema.
--
-- There is no row-level security in D1. Instead, the Worker scopes every query to the signed-in
-- user's id (cloudflare/src/planner.js) and the browser never talks to the database directly.
-- The constraints and triggers below are a second lock on the most important rules.
--
-- Conventions
--   ids          TEXT UUIDs generated by the client (crypto.randomUUID())
--   booleans     INTEGER 0/1
--   timestamps   TEXT ISO-8601 UTC, e.g. 2026-11-04T18:30:00.000Z
--   deadlines    due_date 'YYYY-MM-DD' + due_time 'HH:MM' local wall-clock, never time-zone timestamps
--   scheduled    scheduled_start 'YYYY-MM-DDTHH:MM' local wall-clock

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  google_sub TEXT UNIQUE,
  display_name TEXT,
  time_zone TEXT NOT NULL DEFAULT 'America/Los_Angeles',
  settings TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(settings)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Only a SHA-256 hash of each session token is stored, so a database leak can't be replayed as a login.
CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  expires_at TEXT NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

-- Magic sign-in links: single use, short-lived, hashed like sessions.
CREATE TABLE login_tokens (
  token_hash TEXT PRIMARY KEY,
  email TEXT NOT NULL COLLATE NOCASE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  expires_at TEXT NOT NULL,
  used_at TEXT
);
CREATE INDEX login_tokens_email_idx ON login_tokens (email, created_at);

CREATE TABLE classes (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
  teacher TEXT,
  period TEXT,
  -- D1 caps LIKE/GLOB patterns at 50 characters, so checks use short patterns plus substr().
  color TEXT NOT NULL DEFAULT '#c48b34' CHECK (length(color) = 7 AND substr(color, 1, 1) = '#' AND NOT (lower(substr(color, 2)) GLOB '*[^0-9a-f]*')),
  code TEXT CHECK (length(code) <= 4),
  axis_key TEXT,
  archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (user_id, axis_key)
);
CREATE INDEX classes_user_idx ON classes (user_id, created_at);

CREATE TABLE items (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  class_id TEXT REFERENCES classes (id) ON DELETE SET NULL,
  type TEXT NOT NULL DEFAULT 'task' CHECK (type IN ('assignment', 'test', 'task', 'event')),
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 300),
  notes TEXT NOT NULL DEFAULT '',
  priority TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high')),
  due_date TEXT CHECK (due_date IS NULL OR (length(due_date) = 10 AND date(due_date) IS due_date)),
  due_time TEXT CHECK (due_time IS NULL OR due_time GLOB '[0-2][0-9]:[0-5][0-9]*'),
  scheduled_start TEXT CHECK (scheduled_start IS NULL OR (
    -- IS, not =, because date() returns NULL for impossible dates and a NULL check would pass.
    date(substr(scheduled_start, 1, 10)) IS substr(scheduled_start, 1, 10) AND substr(scheduled_start, 11, 1) = 'T'
    AND substr(scheduled_start, 12) GLOB '[0-2][0-9]:[0-5][0-9]*')),
  duration_minutes INTEGER NOT NULL DEFAULT 45 CHECK (duration_minutes BETWEEN 5 AND 1440),
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  completed_at TEXT,
  source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'axis')),
  axis_uid TEXT,
  axis_missing INTEGER NOT NULL DEFAULT 0 CHECK (axis_missing IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT,
  UNIQUE (user_id, axis_uid)
);
CREATE INDEX items_user_due_idx ON items (user_id, due_date) WHERE deleted_at IS NULL;
CREATE INDEX items_user_scheduled_idx ON items (user_id, scheduled_start) WHERE deleted_at IS NULL;

-- An item may only point at a class owned by the same user (Postgres used a composite foreign key).
CREATE TRIGGER items_class_owner_insert BEFORE INSERT ON items
WHEN NEW.class_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM classes WHERE id = NEW.class_id AND user_id = NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'item class belongs to another user'); END;
CREATE TRIGGER items_class_owner_update BEFORE UPDATE OF class_id, user_id ON items
WHEN NEW.class_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM classes WHERE id = NEW.class_id AND user_id = NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'item class belongs to another user'); END;

-- Rows never change owner.
CREATE TRIGGER items_owner_fixed BEFORE UPDATE OF user_id ON items WHEN NEW.user_id IS NOT OLD.user_id
BEGIN SELECT RAISE(ABORT, 'items cannot change owner'); END;
CREATE TRIGGER classes_owner_fixed BEFORE UPDATE OF user_id ON classes WHEN NEW.user_id IS NOT OLD.user_id
BEGIN SELECT RAISE(ABORT, 'classes cannot change owner'); END;

-- The feed link works like a password. Only the Worker's Axis code reads it, and no API returns it.
CREATE TABLE axis_connections (
  user_id TEXT PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
  ical_url TEXT NOT NULL,
  last_synced_at TEXT,
  -- Set when any sync starts, so the cron rotates through connections and a broken feed can't starve the rest.
  last_attempted_at TEXT,
  last_error TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX axis_connections_due_idx ON axis_connections (last_attempted_at);

CREATE TABLE sync_runs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  finished_at TEXT,
  status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'ok', 'error')),
  added INTEGER NOT NULL DEFAULT 0,
  updated INTEGER NOT NULL DEFAULT 0,
  removed INTEGER NOT NULL DEFAULT 0,
  error TEXT
);
CREATE INDEX sync_runs_user_started_idx ON sync_runs (user_id, started_at DESC);

-- Created now so the shape is settled; delivery arrives in Phase 3.
CREATE TABLE reminders (
  id TEXT PRIMARY KEY,
  item_id TEXT NOT NULL REFERENCES items (id) ON DELETE CASCADE,
  offset_minutes INTEGER NOT NULL DEFAULT 60 CHECK (offset_minutes >= 0),
  fire_at TEXT,
  sent_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX reminders_unsent_idx ON reminders (fire_at) WHERE sent_at IS NULL;
